import logging
import os
from .abstract_core_logger_wrapper import (configure_config_logger, configure_scopes_logger,
                                                        configure_aliases_logger, configure_device_pool_logger,
                                                        configure_metadata_logger, core_logger, create_logger,
                                                        ExtendedFormatter)


def want_debug_details():
    """Check if we want to have debug details inside logs"""
    return core_logger.debug_level is not None


def mark_tc_phase(msg):
    """
    Put TestCase related marker into all ute_ue logs requiring that info

    :param msg: TC related message (should show TC phase)
    :return: None
    """
    core_logger.mark_tc_phase(msg=msg, additional_loggers=["ute_ue", "ute_ue.ue"])


class UeInfoExtendedFormatter(ExtendedFormatter):
    """Library developer needs also library-AREA to help in troubleshooting"""
    def __init__(self):
        """Initialize base class with format string containing %(area)s %(ue_name)s %(ue_id)s"""
        log_fmt = "%(asctime)s | %(levelname)-8s | %(area)-15s %(ue_name)-10s %(ue_id)-10s | " \
                  "%(message)s /// %(threadName)-11s: %(filename)s(%(lineno)d)"
        super().__init__(fmt=log_fmt)

    def format(self, record):
        """Ensure log record has .area .ue_name .ue_id to allow for "%(area)s %(ue_name)s %(ue_id)s" in format string"""
        if not hasattr(record, "area"):
            record.area = " "
        if not hasattr(record, "ue_name"):
            record.ue_name = " "
        if not hasattr(record, "ue_id"):
            record.ue_id = ""
        elif record.ue_id and (not record.ue_id.startswith("UE")):
            record.ue_id = f"UE:{record.ue_id}"
        line = super().format(record)
        return line


class LoggerAdapter4EmptyExtra(logging.LoggerAdapter):
    """An adapter that fills 'extra' key passed to log records but doesn't overwrite existing extra subkeys."""

    def process(self, msg, kwargs):
        """
        Process the logging message and keyword arguments passed in to
        a logging call to insert contextual information.
        If such information already exists it is not overwritten.
        """
        if 'extra' not in kwargs:
            kwargs["extra"] = self.extra
        else:
            for update_key in self.extra:
                if update_key not in kwargs["extra"]:
                    kwargs["extra"][update_key] = self.extra[update_key]
        return msg, kwargs

    def log(self, level, msg, *args, **kwargs):
        """
        Allow stacking LoggerAdapters.
        Such stacked adapters perform their process() in stacking order
        """
        if self.isEnabledFor(level):
            logger_adapter = self
            max_adapters_nesting_level = 2
            nesting_level = 0
            while isinstance(logger_adapter, logging.LoggerAdapter):
                msg, kwargs = logger_adapter.process(msg, kwargs)
                nesting_level += 1
                if nesting_level > max_adapters_nesting_level:
                    err_msg = "Exceeded nesting level of LoggerAdapters - processing not finished for"
                    self.logger._log(logging.ERROR, f"{err_msg} msg={msg}, kwargs={kwargs}", args, **kwargs)
                    return
                logger_adapter = logger_adapter.logger
            self.logger._log(level, msg, args, **kwargs)


def configure_loggers(formatter=None, debug_formatter=None):
    """Configure all loggers for library."""
    if want_debug_details():
        configure_debug_loggers()
    create_all_ues_log(formatter=formatter, debug_formatter=debug_formatter)  # TODO: should it be ute_ue.ue or just ute_ue?
    create_metadata_logger()


def configure_debug_loggers():
    """Configure all loggers required for library troubleshooting"""
    if 'al.config' not in core_logger.active_loggers:
        configure_config_logger()
    else:
        exchange_logpath(logger=logging.getLogger('al.config'), new_logpath=core_logger.get_logging_path())
    if 'al.aliases' not in core_logger.active_loggers:
        configure_aliases_logger()
    else:
        exchange_logpath(logger=logging.getLogger('al.aliases'), new_logpath=core_logger.get_logging_path())
    if 'al.scopes' not in core_logger.active_loggers:
        configure_scopes_logger()
    else:
        exchange_logpath(logger=logging.getLogger('al.scopes'), new_logpath=core_logger.get_logging_path())
    if 'al.devicepool' not in core_logger.active_loggers:
        configure_device_pool_logger()
    else:
        exchange_logpath(logger=logging.getLogger('al.devicepool'), new_logpath=core_logger.get_logging_path())


def create_metadata_logger():
    """Create logger for keyword metadata logging"""
    if 'ute_ue.kw_data' not in core_logger.active_loggers:
        configure_metadata_logger()
    else:
        exchange_logpath(logger=logging.getLogger('ute_ue.kw_data'), new_logpath=core_logger.get_logging_path())


def set_formatter_for_file_handlers(logger_name, formatter, log_file):
    """Set formatter for all handlers of logger"""
    logger = logging.getLogger(logger_name)
    for hdlr in logger.handlers:
        if isinstance(hdlr, logging.FileHandler) and hdlr.baseFilename.endswith(log_file):
            hdlr.setFormatter(formatter)


def create_all_ues_log(formatter=None, debug_formatter=None):
    """Create logger showing actions on all UEs"""
    logger_name = 'ute_ue'  # TODO: jak już istniał i miał te handlery to im tylko zmienić ścieżkę i formattery
    if logger_name not in core_logger.active_loggers:
        _create_all_ues_logger(logger_name, formatter, debug_formatter)
    else:
        _modify_all_ues_logger(logger_name, formatter, debug_formatter)


def _create_all_ues_logger(logger_name, formatter=None, debug_formatter=None):
    logger = create_logger(logger_name, 'ute_ue.log', log_level=logging.INFO)
    if formatter is None:
        formatter = ExtendedFormatter(fmt="%(asctime)s %(levelname)-10s |%(message)s")
        set_formatter_for_file_handlers(logger_name, formatter=formatter, log_file='ute_ue.log')
    if want_debug_details():
        logger.setLevel(core_logger.TRACE)  # deactivate logger filtering-out log-records of level DEBUG/TRACE
        setup_debugging_file_handler(logger_name, debug_formatter=debug_formatter)
    logger.propagate = False


def _modify_all_ues_logger(logger_name, formatter=None, debug_formatter=None):
    logger = logging.getLogger(logger_name)
    if formatter is None:
        formatter = ExtendedFormatter(fmt="%(asctime)s %(levelname)-10s |%(message)s")
        set_formatter_for_file_handlers(logger_name, formatter=formatter, log_file='ute_ue.log')
    if want_debug_details():
        logger.setLevel(core_logger.TRACE)  # deactivate logger filtering-out log-records of level DEBUG/TRACE
        set_formatter_for_file_handlers(logger_name, formatter=debug_formatter, log_file='ute_ue.debug.log')
    exchange_logpath(logger=logger, new_logpath=core_logger.get_logging_path())


def setup_debugging_file_handler(logger_name, debug_formatter=None):
    """Configure file handler for library debugging"""
    log_filename = f'{logger_name}.debug.log'
    logfile_full_path = os.path.join(core_logger.logging_path, log_filename)
    if debug_formatter is None:
        debug_formatter = UeInfoExtendedFormatter()
    core_logger.setup_new_file_handler(logger_name=logger_name,
                                       log_level=core_logger.TRACE,
                                       log_filename=logfile_full_path,
                                       formatter=debug_formatter)


def exchange_filename(logger, new_filename):
    """
    Rename logfile configured under given logger to new_filename.

    :param logger: logger to modify
    :param new_filename: target of file rename
    :return: None
    """
    initial_logger = logger
    logger_handlers = _extract_logger_handlers(logger)
    for hdlr in logger_handlers:
        if isinstance(hdlr, logging.FileHandler):
            old_abspath = hdlr.baseFilename
            (path, filename) = os.path.split(old_abspath)
            if filename == new_filename:
                continue
            new_abspath = os.path.join(path, new_filename)
            if os.path.exists(old_abspath):
                hdlr.close()
                _rename_files(initial_logger, old_abspath, new_abspath)
                hdlr.mode = 'a'  # to append new log entries after rename+reopen
                hdlr.baseFilename = new_abspath
                return  # renames first found FileHandler


def exchange_logpath(logger, new_logpath):
    """
    Change location of logfiles configured under given logger.

    :param logger: logger to modify
    :param new_logpath: target location of logs
    :return: None
    """
    initial_logger = logger
    logger_handlers = _extract_logger_handlers(logger)
    for hdlr in logger_handlers:
        if isinstance(hdlr, logging.FileHandler):
            old_abspath = hdlr.baseFilename
            (path, filename) = os.path.split(old_abspath)
            if path == new_logpath:
                continue
            new_abspath = os.path.join(new_logpath, filename)
            if os.path.exists(old_abspath):
                hdlr.close()
                _rename_files(initial_logger, old_abspath, new_abspath)
                hdlr.mode = 'a'  # to append new log entries after rename+reopen
                hdlr.baseFilename = new_abspath


def _extract_logger_handlers(logger):
    """
    Go down in stacked logger adapters till real logger will be reached.
    :param logger:
    :return: Handlers of real logger
    """
    search_level = 1
    initial_logger = logger
    while isinstance(logger, logging.LoggerAdapter):
        if search_level > 20:
            # it is just logging - we don't want to break app because of
            # logging failing to rename it's logs - just make it visible.
            err = "Too many LoggerAdapters stacked !!!"
            err_msg = f"Failed to find logger's FileHandlers. {err}"
            initial_logger.warning(err_msg)
            return []
        logger = logger.logger
        search_level += 1
    return logger.handlers


def _rename_files(logger, old_abspath, new_abspath):
    try:
        if os.path.exists(new_abspath):
            # append content of file at old_abspath into file at new_abspath
            with open(old_abspath) as old:
                old_content = old.read()
            with open(new_abspath, "a") as new:
                new.write(old_content)
            os.remove(old_abspath)
        else:
            os.rename(old_abspath, new_abspath)
    except OSError as err:
        # it is just logging - we don't want to break app because of
        # logging failing to rename it's logs - just make it visible.
        err_msg = f"Failed to rename {old_abspath} to {new_abspath}. {repr(err)}"
        logger.warning(err_msg)


# actions during import:
if want_debug_details():
    configure_debug_loggers()
